WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, COUNT(CASE WHEN merchant = 'Grab' THEN 1 END) AS grab_count, COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END) AS amazon_count, COUNT(DISTINCT account_id) AS distinct_account_ids, APPROX_PERCENTILE(new_group_flag, ARRAY(0.25, 0.5, 0.75)) AS new_group_flag_quartiles, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END), 0), 2) AS session_no_per_refund FROM sessions_transactions GROUP BY CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END ORDER BY new_group_flag_tier DESC NULLS LAST;
